#include <iostream>
#include <optional>
#include <string>

int main() {
    using maybe_int = std::optional<int>;

    auto valueless = [] {
        std::cout << "Valueless: ";
        return maybe_int{0};
    };

    maybe_int x;
    std::cout << x.or_else(valueless).value() << '\n';

    x = 42;
    std::cout << "Has value: ";
    std::cout << x.or_else(valueless).value() << '\n';

    x.reset();
    std::cout << x.or_else(valueless).value() << '\n';
}
